import { ProfilePatch } from './types';

const INVALID_PROFILE = 'invalid profile';

function invalid(): never {
  throw new Error(INVALID_PROFILE);
}

const MAX_DISPLAY_NAME_LENGTH = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function isPlainObject(input: unknown): input is Record<string, unknown> {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return false;
  const prototype = Object.getPrototypeOf(input);
  return prototype === Object.prototype || prototype === null;
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') invalid();
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME_LENGTH) invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value) || value.length > MAX_TAGS) invalid();
  const tags: string[] = [];
  const seen = new Set<string>();
  for (const entry of value) {
    if (typeof entry !== 'string') invalid();
    const trimmed = entry.trim();
    if (trimmed.length < 1 || trimmed.length > MAX_TAG_LENGTH) invalid();
    if (seen.has(trimmed)) invalid();
    seen.add(trimmed);
    tags.push(trimmed);
  }
  return tags;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (!isPlainObject(input)) invalid();

  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') invalid();
  }

  const hasDisplayName = Object.prototype.hasOwnProperty.call(input, 'displayName');
  const hasTags = Object.prototype.hasOwnProperty.call(input, 'tags');

  return {
    displayName: hasDisplayName
      ? { kind: 'set', value: parseDisplayName(input.displayName) }
      : { kind: 'keep' },
    tags: hasTags ? { kind: 'set', value: parseTags(input.tags) } : { kind: 'keep' },
  };
}
